mapper.select:
SELECT label, COUNT(DISTINCT userId) AS value FROM (
    SELECT DATE_FORMAT(create_time, '%Y-%m') AS label, user_id AS userId
    FROM orders        WHERE deleted = 0 AND create_time >= #{from}
    UNION ALL
    SELECT DATE_FORMAT(create_time, '%Y-%m') AS label, user_id AS userId
    FROM booking       WHERE deleted = 0 AND create_time >= #{from}
    UNION ALL
    SELECT DATE_FORMAT(browse_time, '%Y-%m') AS label, user_id AS userId
    FROM browse_history                      WHERE browse_time >= #{from}
) t
GROUP BY label
ORDER BY label ASC
